# SPDX-License-Identifier: MIT
# A media player for LVGL apps on Linux boards: gst-play-1.0 (GStreamer) runs in the background
# through linuxproc.Process and is driven with its keyboard keys. It plays files and http:// streams.
# One process per track: at the end of a track the next one starts.
#
# In the Copper and Code Studio simulator there is no Linux: a stand-in "plays" silent 30-second tracks,
# so the GUI can be designed and tried without a board.

import time

try:
    import linuxproc
except ImportError:
    linuxproc = None

# GStreamer audio output: None for the default (ALSA, the first sound card), or for example
# "fakesink sync=true" to run without a sound card. The environment variable MPY_AUDIO_SINK sets
# it without changing the code.
try:
    import os

    SINK = os.getenv("MPY_AUDIO_SINK")
except (ImportError, AttributeError):
    SINK = None


def _seconds(text):
    # "0:01:02.5" -> 62.5; None for what is not a time
    parts = text.split(":")
    if len(parts) != 3:
        return None
    try:
        return int(parts[0]) * 3600 + int(parts[1]) * 60 + float(parts[2])
    except ValueError:
        return None


class Player:
    # live=True for radio streams: no duration, and the simulator stand-in plays without end.
    def __init__(self, live=False):
        self.live = live
        self.uris = []
        self.index = -1
        self.position = 0.0
        self.duration = None  # None for a live stream
        self.paused = False
        self.volume = 100
        self.playing = False
        self.error = None
        self._last_error = None
        self.process = None
        self._pending = b""
        self._keys = []
        self._key_at = 0
        self._started = 0

    # --- control -------------------------------------------------------------------------------

    def play(self, uris, index=0):
        self.uris = list(uris)
        self._start(index)

    def toggle_pause(self):
        if self.playing:
            self.paused = not self.paused
            self._key(b" ")

    def next(self):
        if self.uris:
            self._start((self.index + 1) % len(self.uris))

    def previous(self):
        if self.uris:
            # After 3 s, the first press goes back to the start of the track, as on most players.
            self._start(self.index if self.position > 3 else (self.index - 1) % len(self.uris))

    def volume_up(self):
        self._set_volume(self.volume + 10)

    def volume_down(self):
        self._set_volume(self.volume - 10)

    def stop(self):
        if self.process:
            self.process.close()
            self.process = None
        self.playing = False
        self.paused = False
        self.position = 0.0

    # --- to call from an LVGL timer, about 5 times a second --------------------------------------

    def update(self):
        if not self.playing:
            return
        if self.process is None:
            self._simulate()
            return
        if self._keys and time.ticks_diff(time.ticks_ms(), self._key_at) >= 150:
            # One key per read of the player: two keys in one read are ignored as an unknown sequence.
            self.process.write(self._keys.pop(0))
            self._key_at = time.ticks_ms()
        self._pending += self.process.read()
        lines = self._pending.replace(b"\r", b"\n").split(b"\n")
        self._pending = lines.pop()
        for line in lines + [self._pending]:
            self._parse(line.strip())
        status = self.process.poll()
        if status is not None:
            self.process.close()
            self.process = None
            self.playing = False
            if status != 0 or self.duration is None:
                # No sound card, a missing file, a stream that does not answer: say so and stop.
                self.error = self._last_error or "player stopped (%d)" % status
            else:
                self.next()  # the track ended

    # --- inside ------------------------------------------------------------------------------------

    def _start(self, index):
        self.stop()
        self.index = index
        self.position = 0.0
        self.duration = None
        self._pending = b""
        self._keys = []
        self._started = time.ticks_ms()
        self.playing = True
        self.error = None
        self._last_error = None
        if linuxproc is None:
            self.duration = None if self.live else 30.0
            return
        argv = ["gst-play-1.0", "--volume=%.2f" % (self.volume / 100)]
        if SINK:
            argv.append("--audiosink=" + SINK)
        uri = self.uris[index]
        argv.append(uri)
        self.process = linuxproc.Process(argv)

    def _key(self, key):
        if self.process:
            self._keys.append(key)

    def _set_volume(self, volume):
        # gst-play changes the volume by 5% with the arrow keys (+ and - change the speed).
        volume = max(0, min(volume, 100))
        steps = (volume - self.volume) // 5
        self.volume = volume
        for _ in range(abs(steps)):
            self._key(b"\x1b[A" if steps > 0 else b"\x1b[B")

    def _parse(self, line):
        if line.startswith(b"ERROR debug information"):
            pass  # the source location in GStreamer, after the message that matters
        elif line.startswith(b"ERROR") or line.startswith(b"WARNING"):
            self._last_error = line.decode("utf-8", "ignore")[:80]
        elif line.startswith(b"Volume: ") and line.endswith(b"%"):
            try:
                self.volume = int(line[8:-1])
            except ValueError:
                pass
        elif b" / " in line and line[:1].isdigit():
            now, _, total = line.partition(b" / ")
            position = _seconds(now.decode())
            if position is not None:
                self.position = position
            total = total.split(b" ")[0].decode()
            duration = _seconds(total)
            # Live streams report no duration, or one of 99:99:99 and more.
            self.duration = duration if duration is not None and duration < 360000 else None

    def _simulate(self):
        if not self.paused:
            self.position = time.ticks_diff(time.ticks_ms(), self._started) / 1000
        else:
            self._started = time.ticks_add(time.ticks_ms(), -int(self.position * 1000))
        if self.duration is not None and self.position >= self.duration:
            self.next()

# SPDX-License-Identifier: MIT
# The music library: the .mp3 files of a folder, with title and artist from their ID3v2 tags.
# MicroPython decodes only UTF-8, so Latin-1 and UTF-16 tags are decoded here by hand.

import os

# On a Linux board this is /usr/local/mpy/fs/music, the "music" folder that mpremote sees as
# :music. Copy songs there with: mpremote fs cp song.mp3 :music/
MUSIC_DIR = "music"


def _syncsafe(data):
    return (data[0] << 21) | (data[1] << 14) | (data[2] << 7) | data[3]


def _text(data):
    if not data:
        return ""
    encoding, body = data[0], data[1:]
    if encoding == 3:  # UTF-8
        return body.decode("utf-8", "ignore").rstrip("\x00")
    if encoding in (1, 2):  # UTF-16 with a byte order mark, or UTF-16 big endian
        little = encoding == 1 and body[:2] == b"\xff\xfe"
        if encoding == 1:
            body = body[2:]
        chars = []
        for i in range(0, len(body) - 1, 2):
            code = body[i] | (body[i + 1] << 8) if little else (body[i] << 8) | body[i + 1]
            if code == 0:
                break
            if code < 0xD800 or code > 0xDFFF:  # surrogate pairs (emoji) are skipped
                chars.append(chr(code))
        return "".join(chars)
    return "".join(chr(b) for b in body if b)  # Latin-1


def tags(path):
    # {"title": ..., "artist": ...}, the keys present in the file's ID3v2 header
    found = {}
    try:
        with open(path, "rb") as source:
            header = source.read(10)
            if len(header) < 10 or header[:3] != b"ID3":
                return found
            version = header[3]
            data = source.read(min(_syncsafe(header[6:10]), 65536))
    except OSError:
        return found
    wanted = {b"TIT2": "title", b"TPE1": "artist"}
    offset = 0
    while offset + 10 <= len(data) and len(found) < 2:
        frame = data[offset:offset + 4]
        if frame[:1] == b"\x00":
            break
        raw = data[offset + 4:offset + 8]
        size = _syncsafe(raw) if version >= 4 else int.from_bytes(raw, "big")
        if frame in wanted:
            found[wanted[frame]] = _text(data[offset + 10:offset + 10 + size])
        offset += 10 + size
    return found


def tracks(folder=MUSIC_DIR):
    # [(path, title, artist)] sorted by file name; title falls back to the file name
    try:
        names = sorted(name for name in os.listdir(folder) if name.lower().endswith(".mp3"))
    except OSError:
        return []
    result = []
    for name in names:
        path = folder + "/" + name
        info = tags(path)
        result.append((path, info.get("title") or name[:-4], info.get("artist") or ""))
    return result
